        </div>

        {/* Action */}
        <div>
          <label style={labelStyle}>Action</label>
          <div style={checkboxGroupStyle}>
            {ACTIONS.map((action) => (
              <label key={action.value} style={checkboxLabelStyle}>
                <input
                  type="checkbox"
                  checked={selectedActions.has(action.value)}
                  onChange={() => handleActionToggle(action.value)}
